-- 0005_storage.sql
-- CivicQuest: the private `mission-photos` bucket and its storage policies.
-- Source: design.md "Storage (Requirement 5)" (Requirements 5.1–5.7).
--
-- Object path (Requirement 5.4): `<school_id>/<class_id>/<completion_id>.jpg`,
-- all three canonical lowercase uuids. The extension is always `.jpg`: the
-- browser re-encodes every photo through a canvas (which strips EXIF/GPS)
-- before upload, and the name is generated by the server, never the client.
--
-- Decisions (also noted in the build log):
--   1. Read only (Requirements 5.5, 5.6): one SELECT policy for
--      `authenticated`. A caller may read an object only when its path parses
--      as above, the completion belongs to that class, the class belongs to
--      that school and the caller's school, and the caller is the class's
--      teacher or an admin of that school. Counselors, partners, Leaders and
--      teachers of other classes match nothing. `anon` has no policy at all.
--      Signed URLs are issued only after this policy passes for the caller
--      (lib/storage/signed-url.ts uses the user's session, not the service
--      role).
--   2. No INSERT, UPDATE, or DELETE policies. Photo upload is out of scope
--      for this build, and the future upload action must do things RLS
--      cannot: rate limiting (20/hour per class), magic-byte sniffing, and
--      linking `mission_completions.photo_path`. Leaving writes to the server
--      (service role, which bypasses RLS but NOT the bucket's type/size
--      limits) keeps the client write surface at zero until that action
--      exists. Add an INSERT policy then, if direct uploads are wanted.
--   3. Path segments are validated with a strict regex BEFORE any uuid cast.
--      Casting arbitrary text to uuid raises, which would turn a malformed
--      object name into an error instead of "no access". The casts sit
--      inside CASE so they are never evaluated for a non-matching name.
--
-- Known limitation (Requirement 5.3): `allowed_mime_types` is checked
-- against the content type the uploader DECLARES, not the file's bytes. A
-- non-image renamed to `.jpg` and declared `image/jpeg` would pass the bucket
-- check. The bucket does reject undeclared/other types and anything over
-- 5,242,880 bytes, storing nothing. Magic-byte verification belongs in the
-- future server-side upload action.

-- ---------------------------------------------------------------------------
-- Bucket (Requirements 5.1, 5.2, 5.3). Idempotent: re-running resets the
-- settings to these values.
-- ---------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'mission-photos',
  'mission-photos',
  false,
  5242880,
  array['image/jpeg', 'image/png', 'image/webp']
)
on conflict (id) do update
  set name               = excluded.name,
      public             = excluded.public,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- ---------------------------------------------------------------------------
-- Path parser. Returns one row of ids for a canonical photo path, or zero
-- rows for anything else (never raises). security invoker: it reads no
-- tables. Lives in `private`, which PostgREST does not expose.
-- ---------------------------------------------------------------------------

create or replace function private.mission_photo_path_ids(p_name text)
returns table (school_id uuid, class_id uuid, completion_id uuid)
language sql
immutable
set search_path = ''
as $$
  select
    case when ok then split_part(p_name, '/', 1)::uuid end,
    case when ok then split_part(p_name, '/', 2)::uuid end,
    case when ok then left(split_part(p_name, '/', 3), 36)::uuid end
  from (
    select coalesce(
      p_name ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.jpg$',
      false
    ) as ok
  ) v
  where ok;
$$;

revoke all on function private.mission_photo_path_ids(text) from public, anon;
grant execute on function private.mission_photo_path_ids(text) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- storage.objects: SELECT only, for the owning class's teacher or the
-- owning school's admin (Requirements 5.5, 5.6). The joined tables are also
-- filtered by their own RLS for the caller, which agrees with these checks.
-- ---------------------------------------------------------------------------

drop policy if exists mission_photos_select on storage.objects;

create policy mission_photos_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'mission-photos'
    and (select public.app_role()) in ('teacher', 'admin')
    and exists (
      select 1
      from private.mission_photo_path_ids(objects.name) p
      join public.classes c
        on c.id = p.class_id
       and c.school_id = p.school_id
      join public.mission_completions mc
        on mc.id = p.completion_id
       and mc.class_id = p.class_id
      where c.school_id = (select public.app_school_id())
        and (
          ((select public.app_role()) = 'teacher' and c.teacher_id = (select auth.uid()))
          or (select public.app_role()) = 'admin'
        )
    )
  );

-- No insert/update/delete policies on storage.objects for this bucket (see
-- decision 2): every client write is denied.
